import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const whirlwindKickCard='a2-p09-r3c3';
export const whirlwindKickScenarios=['whirlwind-kick-ordinary','whirlwind-kick-owner-ordinary','whirlwind-kick-low','whirlwind-kick-dedicated','whirlwind-kick-far','whirlwind-kick-same-faction','whirlwind-kick-water','whirlwind-kick-equal','whirlwind-kick-lower','whirlwind-kick-maai-one-ordinary','whirlwind-kick-maai-two-ordinary','whirlwind-kick-maai-one-dedicated','whirlwind-kick-maai-two-dedicated','whirlwind-kick-evade-ordinary','whirlwind-kick-evade-dedicated','whirlwind-kick-fate','whirlwind-kick-suppressed','whirlwind-kick-silenced','whirlwind-kick-stopped','whirlwind-kick-wrong-owner','whirlwind-kick-decline','whirlwind-kick-noncounter',] as const;
export type WhirlwindKickScenario=typeof whirlwindKickScenarios[number];
export function isWhirlwindKickScenario(name:string):name is WhirlwindKickScenario{return (whirlwindKickScenarios as readonly string[]).includes(name);}
export function whirlwindKickMode(name:WhirlwindKickScenario){const suffix=name.replace('whirlwind-kick-',''),dedicated=!(suffix.includes('ordinary')||['low','decline'].includes(suffix)),owner=dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary',follower=suffix==='water'?'a2-p23-r1c1':suffix==='equal'?'a2-p22-r1c1':suffix==='lower'?'a2-p19-r1c3':null;return {suffix,dedicated,owner,follower};}
export function makeWhirlwindKickPhysical(name:WhirlwindKickScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;warrior?:number;spirit?:number}={}){
 const m=whirlwindKickMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.suffix==='noncounter';let s=createGame(players,entropy(),{startingSeat:prior?3:incoming?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.owner?'大神官ジル':'侍大将のシン','黒騎士ガーウィン','小人のランバ','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??6:p.id===b?11:6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(m.suffix==='low'?5:m.dedicated?0:6))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,whirlwindKickCard),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,d,'a2-p02-r2c3'),takeCard(s,d,'a2-p02-r1c1')];if(m.follower)keep.push(takeCard(s,b,m.follower));if(m.suffix==='same-faction')keep.push(takeCard(s,a,'a2-p24-r2c1'));if(m.suffix.startsWith('maai'))keep.push(takeCard(s,b,'a2-p06-r1c3'),takeCard(s,b,'a2-p06-r2c1'));if(m.suffix.startsWith('evade'))keep.push(takeCard(s,b,'a2-p05-r3c1'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`WHIRLWIND_KICK_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('WHIRLWIND_KICK_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('WHIRLWIND_KICK_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('WHIRLWIND_KICK_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(m.follower&&id===b)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:m.follower});act(id,{type:'PASS_SETUP'});}if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 const starter=incoming?b:a;act(starter,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(starter,{type:'CHOOSE_DRAW',draw:false});if(incoming){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('WHIRLWIND_KICK_FIXTURE_COUNTER_LIMIT');}
 if(!['far','stopped'].includes(m.suffix)){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r2c1',targetId:c});settle();act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
